return items.map(item => {
  const payload = item.json;

  const fields = payload.fields || {};
  const utm = payload.utm || {};
  const consent = payload.consent || {};

  const leadEmail = fields.email
    ? fields.email.toLowerCase().trim()
    : null;

  const leadPhone = fields.phone
    ? fields.phone.replace(/[^\d+]/g, '')
    : null;

  const leadName = fields.name
    ? fields.name.trim()
    : null;

  const externalId = payload.submission_id || null;

  return {
    json: {
      external_id: externalId,
      event_source: payload.form_id || 'website_form',

      lead_name: leadName,
      lead_email: leadEmail,
      lead_phone: leadPhone,
      lead_source: utm.utm_source || 'unknown',

      company: fields.company || null,
      message: fields.message || null,
      budget: fields.budget || null,
      preferred_contact_method: fields.preferred_contact_method || null,

      form_id: payload.form_id || null,
      form_name: payload.form_name || null,
      page_url: payload.page_url || null,
      referrer: payload.referrer || null,
      submitted_at: payload.submitted_at || null,

      privacy_policy_consent: consent.privacy_policy || false,
      marketing_emails_consent: consent.marketing_emails || false,

      raw_payload: payload,

      is_valid: Boolean(externalId && leadEmail && leadName),

      validation_errors: [
        !externalId ? 'missing_external_id' : null,
        !leadEmail ? 'missing_email' : null,
        !leadName ? 'missing_name' : null
      ].filter(Boolean)
    }
  };
});

