return items.map(item => {
  const lead = item.json;

  const shouldFail = true;

  if (shouldFail) {
    return {
      json: {
        ...lead,
        crm_success: false,
        crm_error: true,
        crm_status_code: 503,
        crm_error_message: 'Mock CRM API error: temporary unavailable',
        crm_response: {
          success: false,
          status_code: 503,
          error: {
            code: 'SERVICE_UNAVAILABLE',
            message: 'Mock CRM API error: temporary unavailable',
            type: 'temporary_error'
          },
          request_id: `req_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
          timestamp: new Date().toISOString()
        }
      }
    };
  }

  const crmContactId = `crm_${Date.now()}_${Math.floor(Math.random() * 10000)}`;

  return {
    json: {
      ...lead,
      crm_success: true,
      crm_error: false,
      crm_status_code: 201,
      lead_external_id: crmContactId,
      crm_response: {
        success: true,
        status_code: 201,
        data: {
          crm_contact_id: crmContactId,
          crm_status: 'created',
          crm_created_at: new Date().toISOString()
        },
        request_id: `req_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
        timestamp: new Date().toISOString()
      }
    }
  };
});

